package com.thangit.boardinghouse.service;

import static org.assertj.core.api.Assertions.*;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.dto.request.accountant.AccountantRequests.*;
import com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.*;
import com.thangit.boardinghouse.repository.*;
import com.thangit.boardinghouse.security.*;
import com.thangit.boardinghouse.service.impl.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

@EnabledIfSystemProperty(named="prompt10.mysql",matches="true")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ManagementFinanceMysqlTest {
 final CheckoutSettlementMysqlTest b=new CheckoutSettlementMysqlTest();final DepositLedgerMysqlTest f=b.f;
 ManagementFinanceRepository repo;ManagementFinanceService service;FinancialReconciliation reconciliation;AccountantPortalServiceImpl accounting;CheckoutSettlementMysqlTest.Case a;
 LocalDate start=LocalDate.now().withDayOfMonth(1),end=start.plusMonths(1).minusDays(1);
 @BeforeAll void setup()throws Exception{f.setup("prompt10_finance_test_",null);b.workflow=f.checkoutWorkflow;b.billing=new MonthlyBillingService(f.db);b.invoices=new AdminInvoiceRepository(f.db);b.invoiceService=new AdminInvoiceServiceImpl(b.invoices);repo=new ManagementFinanceRepository(f.db);service=new ManagementFinanceService(f.db,repo,new PropertyAuthorization(f.db,new SecurityAudit(f.db)));reconciliation=new FinancialReconciliation(f.db);accounting=new AccountantPortalServiceImpl(f.accounting);}
 @BeforeEach void fixture(){a=b.active("0",false);}
 BigDecimal n(String v){return new BigDecimal(v);}String key(){return UUID.randomUUID().toString();}
 Map<String,BigDecimal> totals(){return repo.summary(List.of(a.property()),start,end);}
 long invoice(){return b.oldDebt(a,"3000000");}
 void pay(long id,String amount,String key){f.run(()->b.invoiceService.payment(f.owner,id,key,new RecordPayment(n(amount),"CASH",start.atStartOfDay(),null,"Synthetic evidence",null)));}
 long voucher(String category){return ((Number)f.inTx(()->accounting.createVoucher(f.accountant,new VoucherCreate(a.property(),"Synthetic supplier",n("2000000"),category,"CASH",LocalDate.now(),"Synthetic expense"))).get("id")).longValue();}
 void submit(long id){f.run(()->accounting.submitVoucher(f.accountant,id,new Versioned(0)));}
 void approve(long id){f.run(()->service.approve(f.owner,id,new ManagementFinanceService.Decision(1,"Approved synthetic evidence"),true));}
 ManagementFinanceService.PayVoucher payment(){return new ManagementFinanceService.PayVoucher(2,LocalDateTime.now().minusSeconds(1).withNano(0),key(),"Synthetic receipt");}
 void paid(long id){var r=payment();f.run(()->service.pay(f.accountant,id,key(),r));}
 long period(){return f.insert("INSERT INTO accounting_periods(property_id,period_code,start_date,end_date) VALUES("+a.property()+",'"+start.toString().substring(0,7)+"','"+start+"','"+end+"')");}
 @Test void tc01_issuedObligationIsNotCash(){invoice();assertThat(totals().get("periodInvoiceObligations")).isEqualByComparingTo("3000000");assertThat(totals().get("cashIn")).isZero();}
 @Test void tc02_partialPayment(){long i=invoice();pay(i,"1000000",key());assertThat(totals().get("serviceCashIn")).isEqualByComparingTo("1000000");assertThat(totals().get("outstandingDebt")).isEqualByComparingTo("2000000");}
 @Test void tc03_fullPayment(){long i=invoice();pay(i,"3000000",key());assertThat(totals().get("outstandingDebt")).isZero();}
 @Test void tc04_oldDebtIsNotAddedToNextObligation(){long i=invoice();f.db.sql("UPDATE invoices SET billing_period=:prior WHERE id=:id").param("prior",start.minusMonths(1)).param("id",i).update();invoice();assertThat(totals().get("outstandingDebt")).isEqualByComparingTo("6000000");assertThat(totals().get("periodInvoiceObligations")).isEqualByComparingTo("3000000");}
 @Test void tc05_depositIsCashButNotServiceIncome(){var x=f.booking("3000000");f.run(()->f.ledger.collect(f.accountant,x.deposit(),key(),f.cash("3000000")));var t=repo.summary(List.of(x.property()),start,end);assertThat(t.get("depositCashIn")).isEqualByComparingTo("3000000");assertThat(t.get("netServiceCollections")).isZero();}
 @Test void tc08_transferDoesNotCreateCash(){var x=f.booking("3000000");f.run(()->f.ledger.collect(f.accountant,x.deposit(),key(),f.cash("3000000")));f.contract(x,"3000000");var t=repo.summary(List.of(x.property()),start,end);assertThat(t.get("cashIn")).isEqualByComparingTo("3000000");assertThat(t.get("heldDeposits")).isEqualByComparingTo("3000000");}
 @Test void tc06_refundChangesCashOnlyWhenPaid(){var x=f.booking("3000000");f.run(()->f.ledger.collect(f.accountant,x.deposit(),key(),f.cash("3000000")));long r=f.cancelAndRequest(x,"2000000","1000000");f.run(()->f.ledger.approveRefund(f.owner,x.deposit(),r));assertThat(repo.summary(List.of(x.property()),start,end).get("depositCashOut")).isZero();f.run(()->f.ledger.payRefund(f.accountant,x.deposit(),r,key(),f.cash("2000000")));var t=repo.summary(List.of(x.property()),start,end);assertThat(t.get("depositCashOut")).isEqualByComparingTo("2000000");assertThat(t.get("heldDeposits")).isZero();assertThat(t.get("confirmedCosts")).isZero();}
 @Test void tc07_offsetIsNotCash(){var x=f.settlement("3000000","1000000","400000");long property=f.db.sql("SELECT property_id FROM tenant_deposits WHERE id=:id").param("id",x.deposit()).query(Long.class).single();var t=repo.summary(List.of(property),start,end);assertThat(t.get("cashIn")).isEqualByComparingTo("3000000");assertThat(t.get("serviceCashIn")).isZero();assertThat(t.get("heldDeposits")).isEqualByComparingTo("1600000");}
 @Test void tc09_pendingPaymentIsNotCash(){long i=invoice();f.db.sql("INSERT INTO payments(invoice_id,property_id,tenant_id,receipt_code,amount,payment_method,paid_at,status,transaction_type) VALUES(:i,:p,5,:code,1000000,'CASH',NOW(),'PENDING','PAYMENT')").param("i",i).param("p",a.property()).param("code",key()).update();assertThat(totals().get("cashIn")).isZero();}
 @Test void tc10_rejectedPaymentIsNotCash(){long i=invoice();f.db.sql("INSERT INTO payments(invoice_id,property_id,tenant_id,receipt_code,amount,payment_method,paid_at,status,transaction_type) VALUES(:i,:p,5,:code,1000000,'CASH',NOW(),'REJECTED','PAYMENT')").param("i",i).param("p",a.property()).param("code",key()).update();assertThat(totals().get("cashIn")).isZero();}
 @Test void tc11_reversalRemovesCashExactlyOnce(){long i=invoice();pay(i,"1000000",key());long p=f.db.sql("SELECT id FROM payments WHERE invoice_id=:i").param("i",i).query(Long.class).single();f.run(()->accounting.reversePayment(f.accountant,p,new Reason("Synthetic erroneous payment",0)));assertThat(totals().get("cashIn")).isZero();assertThat(totals().get("outstandingDebt")).isEqualByComparingTo("3000000");assertThatThrownBy(()->f.run(()->accounting.reversePayment(f.accountant,p,new Reason("Repeated",0)))).isInstanceOf(RuntimeException.class);}
 @Test void tc12_idempotentPayment(){long i=invoice();String k=key();pay(i,"1000000",k);pay(i,"1000000",k);assertThat(totals().get("cashIn")).isEqualByComparingTo("1000000");}
 @Test void tc13_referenceCannotBeRepostedByAnotherRole(){long i=invoice();String reference=key();f.run(()->b.invoiceService.payment(f.owner,i,key(),new RecordPayment(n("1000000"),"BANK_TRANSFER",start.atStartOfDay(),reference,"Bank evidence",null)));assertThatThrownBy(()->f.run(()->accounting.createPayment(f.accountant,key(),new PaymentCreate(i,n("1000000"),"BANK_TRANSFER",start.atStartOfDay(),reference,"Same bank event",false)))).isInstanceOf(RuntimeException.class);assertThat(totals().get("cashIn")).isEqualByComparingTo("1000000");}
 @Test void tc14_draftVoucherIsNotCash(){voucher("REPAIR");assertThat(totals().get("cashOut")).isZero();assertThat(totals().get("confirmedCosts")).isZero();}
 @Test void tc15_submittedVoucherIsNotCash(){long v=voucher("REPAIR");submit(v);assertThat(totals().get("cashOut")).isZero();assertThat(totals().get("pendingVouchers")).isEqualByComparingTo("1");}
 @Test void tc16_paidVoucherUsesPaymentDate(){long v=voucher("REPAIR");submit(v);approve(v);paid(v);assertThat(totals().get("cashOut")).isEqualByComparingTo("2000000");assertThat(totals().get("expensePayables")).isZero();}
 @Test void tc17_voucherCannotBePaidTwice(){long v=voucher("REPAIR");submit(v);approve(v);var request=payment();String k=key();f.run(()->service.pay(f.accountant,v,k,request));f.run(()->service.pay(f.accountant,v,k,request));assertThatThrownBy(()->paid(v)).isInstanceOf(RuntimeException.class);assertThat(totals().get("cashOut")).isEqualByComparingTo("2000000");}
 @Test void tc18_repairCostIsSeparateFromPayable(){long v=voucher("REPAIR");submit(v);approve(v);assertThat(totals().get("confirmedCosts")).isEqualByComparingTo("2000000");assertThat(totals().get("expensePayables")).isEqualByComparingTo("2000000");assertThat(totals().get("cashOut")).isZero();assertThat(repo.expenses(List.of(a.property()),start,end).getFirst().get("category")).isEqualTo("REPAIR");}
 @Test void tc19_assetPurchaseIsNotOperatingCost(){long v=voucher("ASSET_PURCHASE");submit(v);approve(v);paid(v);assertThat(totals().get("confirmedCosts")).isZero();assertThat(totals().get("cashOut")).isEqualByComparingTo("2000000");}
 @Test void tc20_netCashIsCashInMinusCashOut(){long i=invoice();pay(i,"3000000",key());long v=voucher("REPAIR");submit(v);approve(v);paid(v);assertThat(totals().get("netCashFlow")).isEqualByComparingTo("1000000");}
 @Test void tc21_doesNotClaimAccountingProfit(){var r=service.report(f.owner,a.property(),start,end);assertThat(r.get("recognizedRevenueSupported")).isEqualTo(false);assertThat(r.get("accountingProfitSupported")).isEqualTo(false);}
 @Test void tc22_paymentDoesNotMoveInvoicePeriod(){long i=invoice();f.db.sql("UPDATE invoices SET billing_period=:prior WHERE id=:id").param("prior",start.minusMonths(1)).param("id",i).update();pay(i,"3000000",key());assertThat(totals().get("periodInvoiceObligations")).isZero();assertThat(totals().get("serviceCashIn")).isEqualByComparingTo("3000000");assertThat(repo.summary(List.of(a.property()),start.minusMonths(1),start.minusDays(1)).get("periodInvoiceObligations")).isEqualByComparingTo("3000000");}
 @Test void tc23_advanceIsUnallocatedNotRevenue(){f.run(()->accounting.createOtherIncome(f.accountant,new OtherIncomeCreate(a.property(),"PREPAYMENT",n("1000000"),LocalDate.now(),"Advance before service","CASH")));assertThat(totals().get("customerAdvances")).isEqualByComparingTo("1000000");assertThat(totals().get("netServiceCollections")).isZero();assertThat(totals().get("outstandingDebt")).isZero();}
 @Test void tc24_ownerAndAccountantShareDefinitions(){long i=invoice();pay(i,"1000000",key());assertThat(service.report(f.owner,a.property(),start,end).get("summary")).isEqualTo(service.report(f.accountant,a.property(),start,end).get("summary"));}
 @Test void tc25_managerOutsideScopeIsDenied(){assertThatThrownBy(()->service.report(new AuthenticatedUser(2L,"test",RoleCode.MANAGER),a.property(),start,end)).isInstanceOf(RuntimeException.class);}
 @Test void tc26_tenantCannotReadFinance(){assertThatThrownBy(()->service.report(f.tenant,a.property(),start,end)).isInstanceOf(RuntimeException.class);}
 @Test void tc27_technicianCannotReadFinance(){assertThatThrownBy(()->service.report(new AuthenticatedUser(6L,"test",RoleCode.TECHNICIAN),a.property(),start,end)).isInstanceOf(RuntimeException.class);}
 @Test void tc28_closedPeriodBlocksOwnerAlternatePaymentApi(){long i=invoice(),p=period();f.run(()->accounting.closePeriod(f.accountant,p,new PeriodAction(0,"Checked")));assertThatThrownBy(()->pay(i,"1000000",key())).isInstanceOf(RuntimeException.class);}
 @Test void tc29_reopenRequiresPermission(){long p=period();f.run(()->accounting.closePeriod(f.accountant,p,new PeriodAction(0,"Checked")));assertThatThrownBy(()->f.run(()->accounting.reopenPeriod(f.accountant,p,new PeriodAction(1,"Reopen")))).isInstanceOf(RuntimeException.class);}
 @Test void tc30_closedPeriodBlocksReversal(){long i=invoice();pay(i,"1000000",key());long py=f.db.sql("SELECT id FROM payments WHERE invoice_id=:i").param("i",i).query(Long.class).single(),p=period();f.run(()->accounting.closePeriod(f.accountant,p,new PeriodAction(0,"Checked")));assertThatThrownBy(()->f.run(()->accounting.reversePayment(f.accountant,py,new Reason("Synthetic",0)))).isInstanceOf(RuntimeException.class);}
 @Test void tc32_reconciliationDetectsOverAllocation(){long i=invoice();pay(i,"1000000",key());f.db.sql("UPDATE payment_allocations SET amount=2000000 WHERE invoice_id=:id").param("id",i).update();var r=reconciliation.run(1,a.property(),start,end);assertThat(((Number)r.get("blockingCount")).intValue()).isGreaterThan(0);long p=period();assertThatThrownBy(()->f.run(()->accounting.closePeriod(f.accountant,p,new PeriodAction(0,"Must block")))).isInstanceOf(RuntimeException.class);}
 @Test void tc33_overpaymentCannotMakeNegativeDebt(){long i=invoice();assertThatThrownBy(()->pay(i,"4000000",key())).isInstanceOf(RuntimeException.class);assertThat(totals().get("outstandingDebt")).isEqualByComparingTo("3000000");}
 @Test void tc31_depositTotalReconcilesToLedger(){var x=f.booking("3000000");f.run(()->f.ledger.collect(f.accountant,x.deposit(),key(),f.cash("3000000")));f.contract(x,"3000000");assertThat(((Number)reconciliation.run(1,x.property(),start,end).get("blockingCount")).intValue()).isZero();}
 @Test void tc34_reversedVoucherCannotReverseTwice(){long v=voucher("REPAIR");submit(v);approve(v);paid(v);f.run(()->service.reverse(f.owner,v,new ManagementFinanceService.Decision(3,"Mistaken")));assertThatThrownBy(()->f.run(()->service.reverse(f.owner,v,new ManagementFinanceService.Decision(4,"Again")))).isInstanceOf(RuntimeException.class);assertThat(totals().get("cashOut")).isZero();}
 @Test void tc35_exportIncludesMoreThanTwoHundredSourcePayments(){long i=invoice();f.run(()->{for(int j=0;j<201;j++)pay(i,"1",key());});var reports=new AdminReportServiceImpl(new AdminReportRepository(f.db));var request=new com.thangit.boardinghouse.dto.request.report.AdminReportRequests.ExportRequest("REVENUE","CSV",List.of(a.property()),start,end,Map.of(),List.of(),false);var job=f.inTx(()->reports.createExport(f.owner,request));String csv=new String(reports.download(f.owner,job.id()),java.nio.charset.StandardCharsets.UTF_8);assertThat(csv.lines().count()).isEqualTo(203);assertThat(reports.report(f.owner,"REVENUE",List.of(a.property()),start,end).details()).hasSize(201);}
 @Test void tc36_exportCannotIncludeAnotherOwnersProperty(){var reports=new AdminReportServiceImpl(new AdminReportRepository(f.db));var other=new AuthenticatedUser(2L,"other-owner@test.invalid",RoleCode.OWNER);var request=new com.thangit.boardinghouse.dto.request.report.AdminReportRequests.ExportRequest("REVENUE","CSV",List.of(a.property()),start,end,Map.of(),List.of(),false);assertThatThrownBy(()->f.run(()->reports.createExport(other,request))).isInstanceOf(RuntimeException.class);}
 @Test void tc37_emptyScopeProducesZeros(){var t=repo.summary(List.of(),start,end);assertThat(t.values()).allMatch(v->v.signum()==0);assertThat(repo.cashEvents(List.of(),start,end)).isEmpty();}
 @Test void tc38_zeroPriorPeriodHasNoFabricatedGrowth(){assertThat(repo.summary(List.of(a.property()),start.minusMonths(1),start.minusDays(1)).get("cashIn")).isZero();assertThat(new AdminReportServiceImpl(new AdminReportRepository(f.db)).overview(f.owner,List.of(a.property()),start,end,null,null).comparison().get("revenueChangePercent")).isNull();assertThat(repo.trend(List.of(a.property()),start.minusMonths(1),start.minusDays(1))).isEmpty();}
 @Test void tc39_concurrentVoucherPaymentHasSingleCashEvent()throws Exception{long v=voucher("REPAIR");submit(v);approve(v);var pool=Executors.newFixedThreadPool(2);var latch=new CountDownLatch(1);try{List<Future<Boolean>> jobs=new ArrayList<>();for(int j=0;j<2;j++)jobs.add(pool.submit(()->{latch.await();try{paid(v);return true;}catch(RuntimeException e){return false;}}));latch.countDown();int success=0;for(var job:jobs)if(job.get(15,TimeUnit.SECONDS))success++;assertThat(success).isEqualTo(1);assertThat(totals().get("cashOut")).isEqualByComparingTo("2000000");}finally{pool.shutdownNow();}}
 @Test void sameBankReferenceCannotBecomeBothInvoiceCashAndDepositOrOtherIncome(){long i=invoice();String reference=key();f.run(()->b.invoiceService.payment(f.owner,i,key(),new RecordPayment(n("1000000"),"BANK_TRANSFER",start.atStartOfDay(),reference,"Bank receipt",null)));var booking=f.booking("1000000");assertThatThrownBy(()->f.run(()->f.ledger.collect(f.accountant,booking.deposit(),key(),new DepositLedgerService.Cash(n("1000000"),"BANK_TRANSFER",LocalDateTime.now().minusSeconds(1),reference,"Bank evidence","Same bank movement",false)))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->f.run(()->accounting.createOtherIncome(f.accountant,key(),new OtherIncomeCreate(a.property(),"OTHER_INCOME",n("1000000"),LocalDate.now(),"Same bank movement","BANK_TRANSFER",reference)))).isInstanceOf(RuntimeException.class);assertThat(totals().get("cashIn")).isEqualByComparingTo("1000000");assertThat(repo.summary(List.of(booking.property()),start,end).get("cashIn")).isZero();}
 @Test void duplicateOtherIncomeKeyIsIdempotent(){var r=new OtherIncomeCreate(a.property(),"OTHER_INCOME",n("500000"),LocalDate.now(),"Synthetic collection","CASH");String k=key();f.run(()->accounting.createOtherIncome(f.accountant,k,r));f.run(()->accounting.createOtherIncome(f.accountant,k,r));assertThat(totals().get("otherCashIn")).isEqualByComparingTo("500000");assertThatThrownBy(()->f.run(()->accounting.createOtherIncome(f.accountant,k,new OtherIncomeCreate(a.property(),"OTHER_INCOME",n("1"),LocalDate.now(),"Different","CASH")))).isInstanceOf(RuntimeException.class);}
 @Test void linkedExpenseIsNotCountedTwice(){long e=f.insert("INSERT INTO expenses(property_id,amount,expense_date,status) VALUES("+a.property()+",2000000,CURRENT_DATE,'CONFIRMED')");long v=((Number)f.inTx(()->accounting.createVoucher(f.accountant,new VoucherCreate(a.property(),"Supplier",n("2000000"),"REPAIR","CASH",LocalDate.now(),"Pay existing cost",e))).get("id")).longValue();submit(v);approve(v);paid(v);assertThat(totals().get("confirmedCosts")).isEqualByComparingTo("2000000");assertThat(totals().get("cashOut")).isEqualByComparingTo("2000000");}
 @Test void voucherDocumentsRequireObjectScopeAndKeepBytes()throws Exception{long v=voucher("REPAIR");var file=new org.springframework.mock.web.MockMultipartFile("file","synthetic.pdf","application/pdf","%PDF-1.4 synthetic".getBytes());long d=((Number)f.inTx(()->service.attach(f.accountant,v,file)).get("id")).longValue();assertThat((byte[])service.document(f.owner,v,d).get("file_content")).isEqualTo(file.getBytes());assertThatThrownBy(()->service.document(new AuthenticatedUser(2L,"other",RoleCode.OWNER),v,d)).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->f.run(()->service.attach(f.accountant,v,new org.springframework.mock.web.MockMultipartFile("file","bad.pdf","application/pdf","executable".getBytes())))).isInstanceOf(RuntimeException.class);}
 @Test void preparingExistingPeriodNeverReopensIt(){long p=period();f.run(()->accounting.closePeriod(f.accountant,p,new PeriodAction(0,"Verified")));var row=f.inTx(()->service.createPeriod(f.accountant,new ManagementFinanceService.PeriodCreate(a.property(),start.toString().substring(0,7))));assertThat(row.get("status")).isEqualTo("CLOSED");assertThatThrownBy(()->f.run(()->service.createPeriod(f.tenant,new ManagementFinanceService.PeriodCreate(a.property(),start.toString().substring(0,7))))).isInstanceOf(RuntimeException.class);}
 @Test void payingApprovedCostFromClosedPriorMonthDoesNotEditTheCost(){long v=voucher("REPAIR");f.db.sql("UPDATE payment_vouchers SET voucher_date=:date WHERE id=:id").param("date",start.minusMonths(1)).param("id",v).update();submit(v);approve(v);f.db.sql("INSERT INTO accounting_periods(property_id,period_code,start_date,end_date,status) VALUES(:property,:code,:start,:end,'CLOSED')").param("property",a.property()).param("code",start.minusMonths(1).toString().substring(0,7)).param("start",start.minusMonths(1)).param("end",start.minusDays(1)).update();paid(v);assertThat(totals().get("cashOut")).isEqualByComparingTo("2000000");assertThat(totals().get("confirmedCosts")).isZero();assertThat(repo.summary(List.of(a.property()),start.minusMonths(1),start.minusDays(1)).get("confirmedCosts")).isEqualByComparingTo("2000000");}
 @Test void paidVoucherCannotBeApprovedByCreator(){long v=voucher("REPAIR");submit(v);assertThatThrownBy(()->f.run(()->service.approve(f.accountant,v,new ManagementFinanceService.Decision(1,"Self approval"),true))).isInstanceOf(RuntimeException.class);}
 @Test void paidVoucherReversalKeepsHistory(){long v=voucher("REPAIR");submit(v);approve(v);paid(v);f.run(()->service.reverse(f.owner,v,new ManagementFinanceService.Decision(3,"Mistaken disbursement")));assertThat(totals().get("cashOut")).isZero();assertThat(f.db.sql("SELECT COUNT(*) FROM financial_audit_logs WHERE entity_type='PAYMENT_VOUCHER' AND entity_id=:id").param("id",v).query(Long.class).single()).isGreaterThanOrEqualTo(4);}
}
